import {simulate,admission} from './model.mjs';
const $=s=>document.querySelector(s),fmt=n=>Math.round(n).toLocaleString('en-GB'),ms=n=>n>=1000?(n/1000).toFixed(2)+' s':n.toFixed(1)+' ms';
let model=simulate(),time=12,timer=null;
function stop(){if(timer)clearInterval(timer);timer=null;$('#play').textContent='Replay scenario';}
function chart(){const series=model.series,max=Math.max(100,...series.flatMap(s=>[s.shared,s.isolated])),x=t=>55+t/60*590,y=n=>218-n/max*170;return `<svg viewBox="0 0 690 270" role="img" aria-label="Operational in-flight records over sixty simulated seconds. Shared FIFO compared with reserved operational capacity."><title>Operational in-flight records</title><text x="55" y="20" font-size="11" fill="#667c69">Operational records in flight</text>${[0,.5,1].map(f=>`<line x1="55" x2="645" y1="${y(f*max)}" y2="${y(f*max)}" stroke="#dde5d9"/><text x="45" y="${y(f*max)+4}" text-anchor="end" font-size="10" fill="#667c69">${fmt(f*max)}</text>`).join('')}${['shared','isolated'].map(m=>`<polyline points="${series.map(s=>x(s.t)+','+y(s[m])).join(' ')}" fill="none" stroke="${m==='shared'?'#ac684e':'#277b66'}" stroke-width="2.5"/>`).join('')}<line x1="${x(5)}" x2="${x(5)}" y1="35" y2="220" stroke="#9da78c" stroke-dasharray="4 4"/><line x1="${x(time)}" x2="${x(time)}" y1="35" y2="220" stroke="#375e70" stroke-dasharray="2 4"/>${[0,15,30,45,60].map(t=>`<text x="${x(t)}" y="242" text-anchor="middle" font-size="10" fill="#667c69">${t}s</text>`).join('')}<text x="109" y="34" font-size="10" fill="#667c69">Policy batch at 5s</text></svg>`;}
function render(){const s=model.series[time],c=model.config,active=time>=c.at,fenced=time>=model.guardAt;
 $('#clock').textContent=time+' seconds';$('#time').value=time;
 for(const m of ['shared','isolated']){$('#'+m+'-p99').textContent=ms(model.summary[m].p99);$('#'+m+'-ops').textContent=fmt(s[m]);$('#'+m+'-bulk').textContent=active?fmt(s[m+'Bulk']):'Not queued';$('#'+m+'-fill').style.width=(active?100*(1-s[m+'Bulk']/c.burst):0)+'%';}
 $('#capacity-note').className='capacity-stamp'+(model.overloaded?' danger':'');$('#capacity-note').textContent=model.overloaded?'Operational demand exceeds its 700-unit reservation. Its own queue grows even with bulk work isolated. Add measured capacity or apply admission control.':'Operational arrivals fit within their reserved capacity. In this idealised model the policy batch adds no operational queueing in the isolated design.';
 $('#guard-title').textContent=fenced?'UK restriction enforced':active?'Source effective · guard in transit':'Revision 7 active';
 $('#guard-detail').textContent=fenced?'Revision 8 blocks affected UK reads and imports. Purge completion is tracked independently.':active?'New UK contact exports stopped at SG. Remote enforcement has not yet been acknowledged.':'The policy batch will commit at t=5s. No change to ordinary eligible deliveries.';
 $('#op-title').textContent=model.overloaded?'Operational reservation exceeded':'Eligible records continue';$('#op-detail').textContent=fmt(s.isolatedCompleted)+' delivered in the isolated model. '+(fenced?'Affected UK contact deliveries are denied; priority never bypasses that restriction.':'The unaffected record stream has its own reserved capacity.');
 $('#bulk-title').textContent=!active?'No reconciliation queued':s.isolatedBulk?'Reconciliation in progress':'Live reconciliation complete';$('#bulk-detail').textContent=!active?'A small policy commit creates a cursor; the expensive scan runs separately.':fmt(s.isolatedBulk)+' tasks remain at 250/s. Modelled completion: t='+model.bulkEnd.isolated.toFixed(0)+'s. Backups and retained audit are outside this counter.';
 $('#chart').innerHTML=chart();
}
for(const id of ['rate','burst'])$('#'+id).addEventListener('change',()=>{stop();model=simulate({rate:+$('#rate').value,burst:+$('#burst').value});render();});
$('#time').addEventListener('input',e=>{stop();time=+e.target.value;render();});
$('#play').addEventListener('click',()=>{if(timer){stop();return;}time=0;render();$('#play').textContent='Pause';timer=setInterval(()=>{time++;render();if(time>=60)stop();},200);});
$('#reset').addEventListener('click',()=>{stop();time=0;render();});
$('#stale').addEventListener('click',()=>{const state={verified:true,validUntil:10,appliedWatermark:8,requiredWatermark:8,homeEpoch:1,placementVersion:1,authorityRevision:8,allowed:false,dataVersion:21,fieldSet:'minimum'};const event={homeEpoch:1,placementVersion:1,authorityRevision:7,dataVersion:22,fieldSet:'contact'};const old=admission(event,state,6),current=admission({...event,authorityRevision:8},state,6);$('#stale-result').textContent='At t=6s: revision 7 → '+old.reason+'. After evaluation against revision 8 → '+current.reason+'. Newer business data does not override the exclusion.';});
render();
